
import type { MoneyValue } from './MoneyValue.js';
import type { PaymentAttemptGiftCardRedemption } from './PaymentAttemptGiftCardRedemption.js';
import type { PaymentAttemptPaymentIntent } from './PaymentAttemptPaymentIntent.js';
import type { PendingPaymentAction } from './PendingPaymentAction.js';

export type OrderPaymentAttempt = { /** RFC3339 timestamp. Format: date-time. */ "completed_at"?: string; "expected_outstanding_money": MoneyValue; /** Reason code for an attempt failure or interrupted payment step, when available. For payment declines, inspect each payment leg's last_payment_error.code. Unmapped values are returned as attempt_failed. */ "failure_code"?: "card_declined" | "insufficient_funds" | "bank_account_closed" | "bank_account_not_found" | "bank_debit_not_authorized" | "bank_account_restricted" | "bank_debit_limit_exceeded" | "authentication_required" | "payment_blocked" | "expired_card" | "incorrect_cvc" | "processing_error" | "payment_method_unavailable" | "payment_method_declined" | "payment_not_completed" | "payment_action_expired" | "payment_method_temporarily_unavailable" | "payment_failed" | "authorization_canceled" | "coupon_reservation_failed" | "invalid_payment_source" | "inventory_unavailable" | "order_changed_before_payment" | "order_payment_customer_mismatch" | "payment_attempt_canceled" | "payment_attempt_expired" | "payment_authorization_canceled" | "payment_authorization_expired" | "payment_confirmation_rejected" | "payment_confirm_outcome_unknown" | "payment_link_capacity_claim_failed" | "payment_link_capacity_validation_failed" | "payment_method_activation_pending" | "payment_method_required" | "payment_option_not_allowed" | "payment_option_unavailable" | "payment_source_binding_failed" | "payment_source_conflict" | "payment_source_not_updatable" | "payment_source_ownership_mismatch" | "receipt_email_failed" | "resource_guarantee_failed" | "setup_action_unavailable" | "setup_canceled" | "setup_cancellation_outcome_unknown" | "setup_cancellation_pending" | "setup_confirmation_outcome_unknown" | "setup_hold_acquisition_failed" | "setup_preparation_outcome_unknown" | "setup_processing" | "setup_result_incomplete" | "setup_status_unknown" | "tip_allocation_sync_failed" | "zero_balance_hold_acquisition_failed" | "attempt_failed" | (string & {}); /** Explanation of an attempt failure or interrupted payment step, when available. For payment declines, inspect each payment leg's last_payment_error.message. */ "failure_message"?: string; "gift_card_redemptions"?: Array<PaymentAttemptGiftCardRedemption>; /** Whether the attempt can continue through PayOrder with action: resume and this payment_attempt_id after any pending client action is complete. If false, check status before starting another payment; the attempt may still be in progress. */ "is_resumable": boolean; "mode": "payment" | "setup" | "settlement" | (string & {}); "payment_attempt_id": string; "payment_intents"?: Array<PaymentAttemptPaymentIntent>; "pending_actions"?: Array<PendingPaymentAction>; /** RFC3339 timestamp. Format: date-time. */ "started_at"?: string; "status": "processing" | "requires_action" | "requires_capture" | "partially_succeeded" | "requires_retry" | "finalizing" | "succeeded" | "failed" | "expired" | "canceled" | (string & {}); };
